// aim.cpp
// World-to-screen projection, cone filtering, and smoothed crosshair delta
// for competitive game clients.
//
// Build standalone smoke test:
//   cl /std:c++17 /DAIM_SMOKE /W4 /O2 aim.cpp /Fe:aim_test.exe
//
// Exported surface:
//   AimInit          – capture screen dimensions and FOV from the game
//   WorldToScreen    – project a 3-D world position to 2-D screen coords
//   GetAimDelta      – return a smoothed crosshair delta toward the nearest
//                      head inside a 240-px screen-space cone

#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include <cmath>
#include <cfloat>
#include <cstdio>

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

struct Vec3 { float x, y, z; };
struct Vec2 { float x, y; };

// View-matrix row-major [4][4].  Supply from the game's renderer.
struct ViewMatrix { float m[4][4]; };

// A single entity snapshot: head position in world space plus a valid flag.
struct Entity {
    Vec3  headPos;
    bool  alive;
};

// Runtime state populated by AimInit.
struct AimState {
    int   screenW;
    int   screenH;
    float smoothFactor;   // 0 < smoothFactor <= 1  (1 = instant, 0.05 = very smooth)
    bool  ready;
};

static AimState g_aim;

// ---------------------------------------------------------------------------
// AimInit
// Capture screen resolution; smoothFactor in (0, 1].
// ---------------------------------------------------------------------------
void AimInit(float smoothFactor)
{
    g_aim.screenW     = GetSystemMetrics(SM_CXSCREEN);
    g_aim.screenH     = GetSystemMetrics(SM_CYSCREEN);
    g_aim.smoothFactor = (smoothFactor > 0.0f && smoothFactor <= 1.0f)
                            ? smoothFactor : 0.10f;
    g_aim.ready       = true;
}

// ---------------------------------------------------------------------------
// WorldToScreen
// Standard 4x4 clip-space projection, perspective divide, viewport remap.
// Returns false when the point is behind the camera (w <= 0).
// ---------------------------------------------------------------------------
bool WorldToScreen(const Vec3& world, const ViewMatrix& vm, Vec2& screen)
{
    const float* m = &vm.m[0][0];

    float clipX = m[0]*world.x + m[1]*world.y + m[2]*world.z  + m[3];
    float clipY = m[4]*world.x + m[5]*world.y + m[6]*world.z  + m[7];
    // clipZ unused for 2-D projection but kept for clarity
    // float clipZ = m[8]*world.x + m[9]*world.y + m[10]*world.z + m[11];
    float clipW = m[12]*world.x + m[13]*world.y + m[14]*world.z + m[15];

    if (clipW <= 0.0f)
        return false;

    float ndcX =  clipX / clipW;
    float ndcY = -clipY / clipW;    // flip Y: NDC +Y is up, screen +Y is down

    screen.x = (ndcX + 1.0f) * 0.5f * static_cast<float>(g_aim.screenW);
    screen.y = (ndcY + 1.0f) * 0.5f * static_cast<float>(g_aim.screenH);
    return true;
}

// ---------------------------------------------------------------------------
// GetAimDelta
// Project every live entity's head, discard anything outside the 240-px cone,
// pick the closest to crosshair, apply exponential smoothing, return delta.
//
// entities    – array of Entity snapshots read from game memory
// count       – number of elements in entities[]
// vm          – current view matrix
// outDelta    – smoothed screen-space delta to apply (pixels)
//
// Returns true when a target was found inside the cone.
// ---------------------------------------------------------------------------
bool GetAimDelta(
    const Entity*     entities,
    int               count,
    const ViewMatrix& vm,
    Vec2&             outDelta)
{
    if (!g_aim.ready || !entities || count <= 0)
        return false;

    const float cx = static_cast<float>(g_aim.screenW) * 0.5f;
    const float cy = static_cast<float>(g_aim.screenH) * 0.5f;
    const float coneRadius = 240.0f;

    // Find the entity whose projected head is inside the cone and closest to
    // the crosshair.
    float bestDist2 = FLT_MAX;
    Vec2  bestScreen{};
    bool  found = false;

    for (int i = 0; i < count; ++i) {
        const Entity& e = entities[i];
        if (!e.alive)
            continue;

        Vec2 s{};
        if (!WorldToScreen(e.headPos, vm, s))
            continue;

        float dx = s.x - cx;
        float dy = s.y - cy;
        float dist2 = dx*dx + dy*dy;

        if (dist2 > coneRadius * coneRadius)
            continue;   // outside 240-px cone

        if (dist2 < bestDist2) {
            bestDist2  = dist2;
            bestScreen = s;
            found      = true;
        }
    }

    if (!found)
        return false;

    // Raw delta from crosshair to best target.
    float rawX = bestScreen.x - cx;
    float rawY = bestScreen.y - cy;

    // Exponential smoothing: blend previous delta toward raw each frame.
    // On the first valid frame the previous state is implicitly zero because
    // outDelta is caller-owned and expected to be zeroed between tracking
    // sessions.
    outDelta.x = outDelta.x + g_aim.smoothFactor * (rawX - outDelta.x);
    outDelta.y = outDelta.y + g_aim.smoothFactor * (rawY - outDelta.y);

    return true;
}

// ---------------------------------------------------------------------------
// Standalone smoke test (define AIM_SMOKE at compile time)
// ---------------------------------------------------------------------------
#ifdef AIM_SMOKE

static ViewMatrix MakeIdentityView()
{
    // Simple orthographic-style matrix where clip == world for the test.
    ViewMatrix vm{};
    vm.m[0][0]  = 1.0f;
    vm.m[5]     = 1.0f;
    vm.m[10]    = 1.0f;
    vm.m[15]    = 1.0f;
    return vm;
}

int main()
{
    AimInit(0.15f);

    // Build a mock identity view that maps world coords 1:1 through clip space.
    // Screen center is (960, 540) on a 1920x1080 display.
    // Place a head at world (0, 0, 0) → NDC (0, 0) → screen center → delta 0.
    // Place a second head 100 px above center.
    ViewMatrix vm = MakeIdentityView();

    // Adjust matrix so that w = 1 and NDC maps to expected pixels.
    // For this test simply force screen-space by overriding worldToScreen
    // indirectly: set head positions that survive the projection.
    // With an identity clip matrix, a point at (ndcX, ndcY, 0, 1) needs
    // worldX = ndcX and worldY = ndcY.
    //   ndcX = screenX / (W/2) - 1
    //   ndcY = -(screenY / (H/2) - 1)   (flipped)
    float W = static_cast<float>(g_aim.screenW);
    float H = static_cast<float>(g_aim.screenH);

    // Entity 0: exactly at crosshair center (should produce delta 0,0).
    // ndcX = 0, ndcY = 0  →  worldX = 0, worldY = 0
    // Entity 1: 100 px right, 50 px above crosshair
    //   screenX = W/2 + 100  →  ndcX = (W/2+100)/(W/2) - 1 = 100/(W/2)
    //   screenY = H/2 - 50   →  ndcY = -( (H/2-50)/(H/2) - 1 ) = 50/(H/2)
    Entity ents[2];
    ents[0].headPos = {0.0f, 0.0f, 0.0f};
    ents[0].alive   = true;

    ents[1].headPos = { 100.0f / (W * 0.5f),
                        50.0f  / (H * 0.5f),
                        0.0f };
    ents[1].alive   = true;

    Vec2 delta{};
    bool hit = GetAimDelta(ents, 2, vm, delta);
    printf("Hit: %s  delta=(%.3f, %.3f)\n", hit ? "yes" : "no", delta.x, delta.y);

    // Drive several frames so smoothing converges.
    for (int f = 0; f < 60; ++f)
        GetAimDelta(ents, 2, vm, delta);
    printf("After 60 frames: delta=(%.3f, %.3f)\n", delta.x, delta.y);

    // Expected: converges toward the smaller raw delta (entity 0 is at center,
    // so the nearest inside cone is entity 0 with delta (0,0)).
    printf("PASS: delta should be near (0, 0)\n");
    return 0;
}

#endif // AIM_SMOKE
